export const DEEPMOON_CATALOGUES = CRATER_DATABASE;

export function getCraterByName(name: string): CraterMetadata | undefined {
  return CRATER_DATABASE.find(c => c.name === name);
}

export function getCratersByClass(cls: 'simple' | 'complex' | 'multiring'): CraterMetadata[] {
  return CRATER_DATABASE.filter(c => c.craterClass === cls);
}

export function getCratersInRegion(minLat: number, maxLat: number, minLon: number, maxLon: number): CraterMetadata[] {
  return CRATER_DATABASE.filter(c =>
    c.lat >= minLat && c.lat <= maxLat && c.lon >= minLon && c.lon <= maxLon
  );
}
